class Solution {
public:
    int getMaxRepetitions(string s1, int n1, string s2, int n2) {
        if (n1 == 0) return 0;
        int s1cnt = 0, s2cnt = 0, index = 0;
        unordered_map<int, pair<int,int>> recall;

        while (s1cnt < n1) {
            for (int i = 0; i < s1.size(); i++) {
                if (s1[i] == s2[index]) {
                    index++;
                    if (index == s2.size()) {
                        s2cnt++;
                        index = 0;
                    }
                }
            }
            s1cnt++;

            if (recall.find(index) != recall.end()) {
                auto [pre_s1cnt, pre_s2cnt] = recall[index];
                int pre_loop_s1 = pre_s1cnt;
                int pre_loop_s2 = pre_s2cnt;

                int in_loop_s1 = s1cnt - pre_s1cnt;
                int in_loop_s2 = s2cnt - pre_s2cnt;

                int loop_count = (n1 - pre_loop_s1) / in_loop_s1;
                s2cnt = pre_loop_s2 + loop_count * in_loop_s2;
                s1cnt = pre_loop_s1 + loop_count * in_loop_s1;
            }
            recall[index] = {s1cnt, s2cnt};
        }
        return s2cnt / n2;
    }
};

