class Solution {
public:
    TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
        if (inorder.size() == 1) return new TreeNode(inorder[0]);
        return build(preorder, inorder, 0, inorder.size() - 1, 0, preorder.size() - 1);
    }

    TreeNode* build(vector<int>& preorder, vector<int>& inorder, int inorderStart, int inorderEnd, int preorderStart, int preorderEnd) {
        if (inorderStart > inorderEnd || preorderStart > preorderEnd) return nullptr;

        int rootValue = preorder[preorderStart];
        TreeNode* root = new TreeNode(rootValue);
        auto it = find(inorder.begin(), inorder.end(), rootValue);
        int rootIndex = std::distance(inorder.begin(), it);
        int left = rootIndex - inorderStart;
        root->left = build(preorder, inorder, inorderStart, rootIndex - 1, preorderStart + 1, preorderStart + left);
        root->right = build(preorder, inorder, rootIndex + 1, inorderEnd, preorderStart + left + 1, preorderEnd);
        return root;
     }
};
