class Solution {
public:
    vector<int> findMinHeightTrees(int n, vector<vector<int>>& edges) {
        if (n == 1) return {0};
        if (n == 2) return {0, 1};

        // Используем статические массивы вместо векторов векторов
        // Это экономит кучу времени на выделении памяти
        vector<int> degree(n, 0);
        vector<int> head(n, -1);
        vector<int> next(edges.size() * 2);
        vector<int> to(edges.size() * 2);

        int edge_idx = 0;
        for (auto& e : edges) {
            int u = e[0], v = e[1];
            degree[u]++; degree[v]++;

            to[edge_idx] = v; next[edge_idx] = head[u]; head[u] = edge_idx++;
            to[edge_idx] = u; next[edge_idx] = head[v]; head[v] = edge_idx++;
        }

        // Очередь на массиве (самый быстрый вариант)
        int q[n];
        int front = 0, rear = 0;
        for (int i = 0; i < n; i++) {
            if (degree[i] == 1) q[rear++] = i;
        }

        int remainingNodes = n;
        while (remainingNodes > 2) {
            int current_layer_size = rear - front;
            remainingNodes -= current_layer_size;

            for (int i = 0; i < current_layer_size; i++) {
                int u = q[front++];
                for (int e = head[u]; e != -1; e = next[e]) {
                    int v = to[e];
                    if (--degree[v] == 1) {
                        q[rear++] = v;
                    }
                }
            }
        }

        vector<int> result;
        while (front < rear) result.push_back(q[front++]);
        return result;
    }
};

